#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_request_facts: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::RequestFacts>> = Mutex::new(None);
  pub static ref IN_brake_facts: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::BrakeFacts>> = Mutex::new(None);
  pub static ref IN_health_qualification: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::HealthQualification>> = Mutex::new(None);
  pub static ref IN_power_facts: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::PowerFacts>> = Mutex::new(None);
  pub static ref IN_cycle_assessment: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment>> = Mutex::new(None);
  pub static ref IN_authorization: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::StartAuthorizationFacts>> = Mutex::new(None);
  pub static ref OUT_test_cycle_directive: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::TestCycleDirective>> = Mutex::new(None);
  pub static ref OUT_applied_lifecycle: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::AppliedLifecycleSnapshot>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_request_facts.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_brake_facts.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_health_qualification.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_power_facts.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_cycle_assessment.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_authorization.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_test_cycle_directive.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_applied_lifecycle.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

